import {
  Box,
  Dropdown,
  type DropdownLayoutValueOption,
  FieldSet,
  FormField,
  Input,
  listItemSelectBuilder,
} from '@wix/design-system';
import React, { useMemo } from 'react';

import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { usePanelContainerElement } from './../ui-components-provider.js';

type SelectWithLabelProps<T extends string | number> = {
  label: string;
  dataHook: string;
  value: T;
  onChange: (value: T) => void;
  options: {
    id: T;
    value: string;
    icon?: React.ReactNode;
  }[];
  logBi: LogBiFn;
  zIndex: string | number;
  /**
   * `'left'` (default) puts the label beside a compact 114px control. `'top'` stacks the label
   * above a full-width control — use it when option labels are long enough to be truncated.
   */
  legendPlacement?: 'left' | 'top';
};

export const SelectWithLabel = <T extends string | number>({
  label,
  dataHook,
  value,
  onChange,
  options,
  logBi,
  zIndex,
  legendPlacement = 'left',
}: SelectWithLabelProps<T>) => {
  const containerEl = usePanelContainerElement();

  const handleSelect = (option: DropdownLayoutValueOption) => {
    logBi?.({ dataHook, value: option.id });

    return onChange(option.id as T);
  };

  const dropdownOptions = useMemo(() => {
    return options.map(option =>
      listItemSelectBuilder({
        size: 'small',
        id: option.id,
        title: option.value,
        label: option.value,
        prefix: option.icon,
      })
    );
  }, [options]);

  const selectedIcon = options.find(option => option.id === value)?.icon;
  const stacked = legendPlacement === 'top';

  const dropdown = (
    <Dropdown
      dataHook={dataHook}
      size="small"
      selectedId={value}
      prefix={selectedIcon && <Input.IconAffix>{selectedIcon}</Input.IconAffix>}
      valueParser={option => option.label}
      popoverProps={{
        zIndex,
        appendTo: containerEl,
        // a stacked control is full-width, so the list sizes to its options instead
        ...(stacked ? {} : { maxWidth: '100px' }),
        placement: stacked ? 'bottom-start' : 'bottom-end',
      }}
      options={dropdownOptions}
      onSelect={handleSelect}
    />
  );

  return (
    <Box direction="vertical">
      <FormField inputWidth="100%">
        {stacked ? (
          <FieldSet columns="auto" legendPlacement="top" legendSize="small" legend={label}>
            {dropdown}
          </FieldSet>
        ) : (
          <FieldSet columns="auto 114px" legendPlacement="left" alignment="center" legend={label}>
            <div />
            {dropdown}
          </FieldSet>
        )}
      </FormField>
    </Box>
  );
};
