import { Box, FieldSet, FormField } from '@wix/design-system';
import React, { type ReactNode, useContext } from 'react';

import { ZIndexContext } from './../../ricos-context/index.js';
import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { InputWithSlider } from './../input-with-slider/input-with-slider.js';

export const NumberInputWithLabel: React.FC<
  {
    label: string;
    dataHook: string;
    suffix: ReactNode;
    value: number | undefined;
    min: number;
    max: number;
    onChange: (value: number | undefined) => void;
    onChangeCommit?: (finalValue: number, originalValue: number) => void;
    commitUnchanged?: boolean;
    logBi: LogBiFn;
    zIndex: string | number;
  } & ({ infoContent: string; tooltipAppendTo: HTMLElement } | { infoContent?: HTMLElement })
> = ({
  label,
  infoContent,
  dataHook,
  suffix,
  onChange,
  onChangeCommit,
  commitUnchanged,
  min,
  max,
  value,
  logBi,
  zIndex,
  ...props
}) => {
  const zIndexService = useContext(ZIndexContext);

  const handleInput = (numberValue: number) => {
    const valueWithinBounds =
      isNaN(numberValue) || numberValue < min ? min : numberValue > max ? max : numberValue;

    logBi?.({ dataHook, value: valueWithinBounds });

    return onChange(valueWithinBounds);
  };

  const handleInputCommit = (finalValue: number, originalValue: number) => {
    const finalWithinBounds =
      isNaN(finalValue) || finalValue < min ? min : finalValue > max ? max : finalValue;
    const originalWithinBounds =
      isNaN(originalValue) || originalValue < min ? min : originalValue > max ? max : originalValue;

    onChangeCommit?.(finalWithinBounds, originalWithinBounds);
  };

  // Four digit numbers need more space than three digit numbers
  const columnWidth = React.useMemo(() => {
    return max > 999 ? 'auto 78px' : 'auto 72px';
  }, [max]);

  return (
    <Box direction="vertical">
      <FormField inputWidth="100%">
        <FieldSet
          columns={columnWidth}
          alignment="center"
          legendPlacement="left"
          legend={label}
          infoContent={typeof infoContent === 'string' ? infoContent : undefined}
          infoTooltipProps={{
            appendTo:
              'tooltipAppendTo' in props
                ? props.tooltipAppendTo
                : el => Boolean(el.getAttribute('data-hook')?.includes('ricos-portal')),
            zIndex: zIndexService.getZIndex('TOOLTIP'),
          }}
          ellipsis
        >
          <div />
          <InputWithSlider
            value={value}
            onChange={handleInput}
            onChangeCommit={handleInputCommit}
            commitUnchanged={commitUnchanged}
            zIndex={zIndex}
            suffix={suffix}
            min={min}
            max={max}
            dataHook={dataHook}
          />
        </FieldSet>
      </FormField>
    </Box>
  );
};
