import type { Item } from '@wix/design-system';
import { Box, SidePanel, Tabs, TextButton } from '@wix/design-system';
import { RevertSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useEffect, useRef, useState } from 'react';

import { ModalServiceContext, RicosContext } from './../../../ricos-context/index.js';
import type { Gradient } from './../../../ricos-types/color-palette-types.js';
import type { LogBiFn } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import type { ThemeColorSwatch } from './../../../_shared/color-manager-utils.js';
import { TRANSPARENT_HEX_COLOR } from './../../../_shared/colors.js';
import {
  getThemeColorTokenOpacity,
  isThemeColorToken,
  setThemeColorTokenOpacity,
} from './../../../_shared/theme-color-token.js';
import {
  combineHexWithOpacity,
  getHexColorFromAlpha,
  getOpacityFromHex,
} from './../../../wix-rich-content-common/index.js';
import {
  Panel,
  useClickOutside,
  usePanelContainerElement,
} from './../../index.js';

import { PanelHeader } from '../../panel-header/panel-header.js';
import { GradientPicker } from './components/gradient-picker/index.js';
import { SimpleColorPicker } from './components/simple-color-picker/index.js';
import {
  COLOR_PICKER_COLOR_ADDED,
  COLOR_PICKER_COLOR_PREVIEW,
  COLOR_PICKER_COLOR_SELECTED,
  FLOATING_COLOR_SWATCHES,
  RESET_BUTTON,
  SAVE_GRADIENT_BUTTON,
} from './data-hooks.js';
import classes from './new-color-picker-scss.js';

const GRADIENT_STOP_COLOR_PICKER_MODAL_ID = 'GRADIENT_STOP_COLOR_PICKER_MODAL';

export type ColorOrGradientValue =
  | { type: 'color'; color: string }
  | { type: 'gradient'; gradient: Gradient };

interface NewColorPickerProps {
  title: string;
  themeColors: ThemeColorSwatch[];
  customColors: string[];
  customGradients?: Gradient[];
  currentColor: string | Gradient | undefined;
  fallbackColor?: string;
  closeModal: () => void;
  onColorSelected: (color: string | undefined) => void;
  onGradientSelected?: (gradient: Gradient) => void;
  onColorAdded: (color: string) => void;
  onColorDeleted?: (color: string) => void;
  onGradientDeleted?: (gradient: Gradient) => void;
  onColorPreview?: (color: string | undefined) => void;
  onColorPreviewStart?: (color: string | undefined) => void;
  onColorPreviewEnd?: () => void;
  onResetColor?: () => void;
  onGradientAdded?: (gradient: Gradient) => void;
  referenceElement: HTMLElement | undefined | null;
  logBi: LogBiFn;
  allowTransparent?: boolean;
  allowGradient?: boolean;
}

const normalizeThemeColorToken = (color: string | undefined): string | undefined =>
  typeof color === 'string' && isThemeColorToken(color.toLowerCase()) ? color.toLowerCase() : color;

const createSimpleGradient = (color: string): Gradient => ({
  type: 'LINEAR',
  stops: [
    { color: combineHexWithOpacity(color, 100), position: 0 },
    { color: '#000000', position: 1 },
  ],
  angle: 90,
});

const getSolidColor = (color: string | Gradient | undefined): string | undefined =>
  typeof color === 'string' ? color : undefined;

const getGradient = (color: string | Gradient | undefined): Gradient | undefined =>
  typeof color === 'object' && color !== null ? color : undefined;

const getFirstGradientColor = (color: string | Gradient | undefined): string | undefined =>
  getGradient(color)?.stops?.[0]?.color;

const getColorTabValue = (
  color: string | Gradient | undefined,
  fallbackColor: string | undefined
): string | undefined => getSolidColor(color) ?? fallbackColor ?? getFirstGradientColor(color);

const getGradientBaseColor = (color: string | undefined): string =>
  getOpacityFromHex(color) === 0 ? '#FFFFFF' : (getHexColorFromAlpha(color) ?? '#FFFFFF');

const getColorOpacity = (color: string | undefined): number =>
  color && isThemeColorToken(color) ? getThemeColorTokenOpacity(color) : getOpacityFromHex(color);

const applyOpacity = (color: string | undefined, opacity: number): string | undefined => {
  if (!color) {
    return color;
  }
  return isThemeColorToken(color)
    ? setThemeColorTokenOpacity(color, opacity)
    : combineHexWithOpacity(color, opacity);
};

export const NewColorPicker: React.FC<NewColorPickerProps> = ({
  title,
  themeColors,
  customColors,
  customGradients = [],
  currentColor: currentColorProp,
  fallbackColor,
  closeModal,
  onColorSelected,
  onGradientSelected,
  onColorAdded: onColorAddedProp,
  onColorDeleted,
  onGradientDeleted,
  onColorPreview,
  onColorPreviewStart: onColorPreviewStartProp,
  onColorPreviewEnd,
  onResetColor: onResetColorProp,
  onGradientAdded,
  referenceElement,
  logBi,
  allowTransparent,
  allowGradient,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);

  const containerEl = usePanelContainerElement();
  const pointerDownStartedInGradientStopPickerRef = useRef(false);

  const isGradient = typeof currentColorProp === 'object' && currentColorProp !== null;
  const [activeTab, setActiveTab] = useState<'color' | 'gradient'>(
    isGradient ? 'gradient' : 'color'
  );
  const [previousColor, setPreviousColor] = useState<string | undefined>(() =>
    getColorTabValue(currentColorProp, fallbackColor)
  );
  const [previousGradient, setPreviousGradient] = useState<Gradient | undefined>(() =>
    getGradient(currentColorProp)
  );

  useEffect(() => {
    if (isGradient) {
      setPreviousGradient(currentColorProp as Gradient);
    } else {
      setPreviousColor(getColorTabValue(currentColorProp, fallbackColor));
    }
  }, [currentColorProp, fallbackColor, isGradient]);

  // The picker can close without a selection (outside click, Escape) while a
  // preview is still painted on the target; end the preview on unmount so it
  // never outlives the picker.
  const onColorPreviewEndRef = useRef(onColorPreviewEnd);
  onColorPreviewEndRef.current = onColorPreviewEnd;
  useEffect(() => () => onColorPreviewEndRef.current?.(), []);

  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      pointerDownStartedInGradientStopPickerRef.current = Boolean(
        (event.target as HTMLElement | null)?.closest('[data-hook^="gradient-color-picker"]')
      );
    };
    const handlePointerUp = () => {
      setTimeout(() => {
        pointerDownStartedInGradientStopPickerRef.current = false;
      }, 0);
    };

    document.addEventListener('pointerdown', handlePointerDown, true);
    document.addEventListener('pointerup', handlePointerUp, true);

    return () => {
      document.removeEventListener('pointerdown', handlePointerDown, true);
      document.removeEventListener('pointerup', handlePointerUp, true);
    };
  }, []);

  const currentColor = normalizeThemeColorToken(
    isGradient
      ? (previousColor ?? getColorTabValue(currentColorProp, fallbackColor))
      : getColorTabValue(currentColorProp, fallbackColor)
  );
  const currentGradient = isGradient
    ? (currentColorProp as Gradient)
    : (previousGradient ?? createSimpleGradient(getGradientBaseColor(currentColor)));
  const currentGradientRef = useRef(currentGradient);
  currentGradientRef.current = currentGradient;

  const currentColorOpacity = getColorOpacity(currentColor);

  const preserveCurrentOpacity = (color: string | undefined) => {
    const selectedColorOpacity = getColorOpacity(color);

    if (
      selectedColorOpacity === 100 &&
      currentColorOpacity !== selectedColorOpacity &&
      currentColor !== TRANSPARENT_HEX_COLOR &&
      currentColor !== '#FFFFFF00'
    ) {
      return applyOpacity(color, currentColorOpacity);
    }

    return color;
  };

  const handleColorSelected = (color: string | undefined) => {
    const colorToUse = preserveCurrentOpacity(color);

    setPreviousColor(colorToUse);
    onColorSelected(colorToUse);
    logBi({ dataHook: COLOR_PICKER_COLOR_SELECTED, value: colorToUse });
  };

  const handleGradientSelected = (gradient: Gradient) => {
    setPreviousGradient(gradient);

    if (onGradientSelected) {
      onGradientSelected(gradient);
      logBi({ dataHook: COLOR_PICKER_COLOR_SELECTED, value: JSON.stringify(gradient) });
    }
  };

  const onColorAdded = (color: string) => {
    onColorAddedProp(color);
    logBi({ dataHook: COLOR_PICKER_COLOR_ADDED, value: color });
  };

  const onColorPreviewStart = (color: string | undefined) => {
    if (onColorPreviewStartProp) {
      const colorToUse = preserveCurrentOpacity(color);
      onColorPreviewStartProp(colorToUse);
      logBi({ dataHook: COLOR_PICKER_COLOR_PREVIEW, value: colorToUse });
    }
  };

  const handleColorPreview = (color: string | undefined) => {
    onColorPreview?.(preserveCurrentOpacity(color));
  };

  const onResetColor = () => {
    if (onResetColorProp) {
      onResetColorProp();
      logBi({ dataHook: RESET_BUTTON });
    }
  };

  const handleGradientSaved = (gradient: Gradient) => {
    setPreviousGradient(gradient);

    if (onGradientAdded) {
      onGradientAdded(gradient);
      logBi({ dataHook: SAVE_GRADIENT_BUTTON, value: JSON.stringify(gradient) });
    }
  };

  const handleGradientStopColorSelected = (index: number, color: string | undefined) => {
    handleGradientSelected({
      ...currentGradientRef.current,
      stops: currentGradientRef.current.stops?.map((stop, stopIndex) =>
        stopIndex === index ? { ...stop, color } : stop
      ),
    });
  };

  const openGradientStopColorPicker = ({
    originalIndex,
    stop,
    referenceElement: colorPickerReferenceElement,
  }: {
    originalIndex: number;
    stop: NonNullable<Gradient['stops']>[number];
    referenceElement: HTMLElement | undefined | null;
  }) => {
    if (!modalService?.togglePluginPanel) {
      return;
    }

    const modalId = GRADIENT_STOP_COLOR_PICKER_MODAL_ID;
    const GradientStopColorPicker = () => (
      <div data-hook={`gradient-color-picker-${originalIndex}`}>
        <NewColorPicker
          title={title}
          themeColors={themeColors}
          customColors={customColors}
          currentColor={stop.color}
          closeModal={() => modalService.closeModal(modalId)}
          onColorSelected={color => handleGradientStopColorSelected(originalIndex, color)}
          onColorAdded={onColorAdded}
          onColorDeleted={onColorDeleted}
          referenceElement={colorPickerReferenceElement}
          logBi={logBi}
          allowTransparent={allowTransparent}
          allowGradient={false}
        />
      </div>
    );

    if (modalService.isModalOpen?.(modalId)) {
      modalService.closeModal(modalId);
    }

    modalService.togglePluginPanel({
      id: modalId,
      Component: GradientStopColorPicker,
      componentProps: {},
      isMobile,
      positioning: {
        referenceElement: colorPickerReferenceElement,
        placement: 'right',
      },
      type: undefined,
      focusReturnElement: colorPickerReferenceElement ?? undefined,
    });
  };

  const handleTabChange = ({ id }: Item) => {
    const newTab = id as 'color' | 'gradient';
    if (newTab === activeTab) {
      return;
    }

    setActiveTab(newTab);

    if (newTab === 'gradient') {
      handleGradientSelected(currentGradient);
    } else if (newTab === 'color') {
      handleColorSelected(currentColor);
    }
  };

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;

      if (pointerDownStartedInGradientStopPickerRef.current) {
        pointerDownStartedInGradientStopPickerRef.current = false;
        return;
      }

      if (
        target?.dataset?.hook === 'tooltip-text' ||
        target?.role === 'tooltip' ||
        containerEl?.contains(target as Node) ||
        referenceElement?.contains(target as Node) ||
        target?.closest('[data-hook^="gradient-color-picker"]')
      ) {
        return;
      }

      closeModal();
    },
  });

  const onCloseButtonClick = () => {
    onColorPreviewEnd?.();
    modalService?.closeModal?.(GRADIENT_STOP_COLOR_PICKER_MODAL_ID);
    closeModal();
  };

  return (
    <Panel
      closeButtonProps={{ onClick: onCloseButtonClick }}
      dataHook={FLOATING_COLOR_SWATCHES}
      width={isMobile ? '100%' : 288}
      maxHeight={isMobile ? undefined : 590}
      height={isMobile ? '100dvh' : 'fit-content'}
    >
      <PanelHeader title={title} className={classes.pickerHeader} />

      {allowGradient && (
        <Tabs
          items={[
            { id: 'color', title: t('ColorPicker_Tab_Color') },
            { id: 'gradient', title: t('ColorPicker_Tab_Gradient') },
          ]}
          activeId={activeTab}
          onClick={handleTabChange}
          size="small"
          type="uniformFull"
          minWidth={0}
        />
      )}

      <Box direction="vertical" overflow="auto">
        {activeTab === 'color' && (
          <SimpleColorPicker
            currentColor={currentColor}
            themeColors={themeColors}
            customColors={customColors}
            onColorSelected={handleColorSelected}
            onColorPreview={onColorPreview ? handleColorPreview : undefined}
            onColorPreviewStart={onColorPreviewStart}
            onColorPreviewEnd={onColorPreviewEnd}
            onColorAdded={onColorAdded}
            onColorDeleted={onColorDeleted}
            allowTransparent={allowTransparent}
          />
        )}

        {activeTab === 'gradient' && allowGradient && (
          <GradientPicker
            value={currentGradient}
            onChange={handleGradientSelected}
            customGradients={customGradients}
            onGradientAdded={onGradientAdded ? handleGradientSaved : undefined}
            onGradientDeleted={onGradientDeleted}
            onColorPickerOpen={openGradientStopColorPicker}
          />
        )}
      </Box>

      {!!onResetColorProp && activeTab === 'color' && (
        <SidePanel.Footer showDivider>
          <Box align="center">
            <TextButton
              onClick={onResetColor}
              weight="normal"
              size="small"
              dataHook={RESET_BUTTON}
              prefixIcon={<RevertSmall />}
            >
              {t('ColorPicker_SetToDefault_ButtonLabel')}
            </TextButton>
          </Box>
        </SidePanel.Footer>
      )}
    </Panel>
  );
};
