import { TIPTAP_CARD_FOOTER_TYPE, TIPTAP_LAYOUT_TYPE } from './../ricos-content/index.js';
import { createRicosNodeExtension } from './../plugin-commons/index.js';

export const cardFooterExtension = createRicosNodeExtension({
  groups: ['no-trailing-node'],
  type: 'html-node',
  name: TIPTAP_CARD_FOOTER_TYPE,
  createExtensionConfig() {
    return {
      name: this.name,
      content: TIPTAP_LAYOUT_TYPE,
      isolating: true,
      selectable: false,
      parseHTML() {
        return [{ tag: 'div[data-card-footer]' }];
      },
      renderHTML() {
        return ['div', { 'data-card-footer': 'true' }, 0];
      },
    };
  },
});
