import {
  combineHexWithOpacity,
  getHexColorFromAlpha,
  getOpacityFromHex,
} from './../wix-rich-content-common/Utils/color-utils.js';

/**
 * Resolves a legacy image-overlay color from the old `imageOpacity` model.
 *
 * Old model: the overlay color combined 2 items: `backdrop` fill and a
 * separate `opacity` (0–opacityMax) dimmed the image to reveal that color.
 * The backdrop may or may not have baked in opacity.
 * New model: the overlay alpha is baked into the hex color itself and displayed
 * on top of the image. Image opacity is deprecated.
 *
 * The legacy effective alpha is the product of two independent dimmings: the
 * alpha already baked into the color, and the amount the image let through
 * (`opacityMax - opacity`, inverted). So we multiply them rather than discard
 * the baked alpha — old content that baked alpha into the color *and* set
 * `opacity < max` renders faithfully. When the color has no alpha channel the
 * baked factor is 1 and this reduces to the plain inversion.
 *
 * At `opacity == max` the image was fully opaque and hid the color entirely, so
 * `inverted` is 0 and the overlay resolves to transparent — faithfully matching
 * the old rendering (no early-out: returning the color as-is would paint a
 * never-visible color on top of the image). Only legacy proto content reaches
 * this function; new content carries the alpha in `BackgroundImage.overlay` and
 * is resolved by `resolveImageOverlay` without ever calling this.
 */
export function resolveBackwardCompatOverlay(
  color: string,
  imageOpacity: number,
  opacityMax: 1 | 100
): string {
  const inverted = (opacityMax - imageOpacity) / opacityMax; // 0..1, amount the image lets through
  const baked = getOpacityFromHex(color) / 100; // 0..1, =1 when the color has no alpha channel
  return combineHexWithOpacity(getHexColorFromAlpha(color), inverted * baked * 100) ?? color;
}
