import {
  generateId,
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_LAYOUT_TYPE,
} from './../ricos-content/index.js';
import { Fragment, type Node as PmNode, Slice } from './../tiptap/pm/model.js';
import { Plugin, PluginKey } from './../tiptap/pm/state.js';

const isCardWrapperType = (typeName: string): boolean =>
  typeName === TIPTAP_CARD_HEADER_TYPE || typeName === TIPTAP_CARD_FOOTER_TYPE;

/**
 * Walks a pasted node tree and:
 *  - unwraps CARD_HEADER / CARD_FOOTER structural wrappers, returning the
 *    inner LAYOUTs as bare blocks — these wrappers only exist inside a CARD
 *    and can't legally re-enter the doc anywhere else, so PM's paste-fitting
 *    logic would otherwise lift them out at the wrong depth (the symptom:
 *    pasting a copied footer into card content creates a new card);
 *  - strips `banner` attrs from LAYOUT nodes so a copied banner layout
 *    pasted into regular content doesn't land in an invalid slot (which
 *    banner-drop-prevention would reject) or leave the doc with two
 *    LAYOUTs sharing the same id;
 *  - regenerates `id` attrs so duplicate ids don't break id-based lookups
 *    (banner-drop-prevention, findNodeById, etc.).
 *
 * `transformPasted` only runs in clipboard paste paths, so manual programmatic
 * inserts (insertContent / insertContentAt) and drag-and-drop are untouched.
 */
const transformPastedNode = (node: PmNode): PmNode[] => {
  // Text nodes carry text, not children — copy preserves text/marks as-is.
  if (node.isText) {
    return [node];
  }

  const newChildren: PmNode[] = [];
  node.content.forEach(child => {
    newChildren.push(...transformPastedNode(child));
  });

  // CARD_HEADER / CARD_FOOTER are PM-only structural wrappers. When they
  // appear in a pasted slice, drop the wrapper and surface its (transformed)
  // children — the inner LAYOUTs have already been demoted by the recursion.
  if (isCardWrapperType(node.type.name)) {
    return newChildren;
  }

  let attrs = node.attrs;
  if (node.type.name === TIPTAP_LAYOUT_TYPE && attrs?.banner) {
    attrs = { ...attrs, banner: null };
  }
  if (attrs?.id) {
    attrs = { ...attrs, id: generateId() };
  }

  return [node.type.create(attrs, Fragment.from(newChildren), node.marks)];
};

export const createCardPastePlugin = (): Plugin => {
  return new Plugin({
    key: new PluginKey('card-paste'),
    props: {
      transformPasted(slice) {
        const newChildren: PmNode[] = [];
        slice.content.forEach(child => {
          newChildren.push(...transformPastedNode(child));
        });
        return new Slice(Fragment.from(newChildren), slice.openStart, slice.openEnd);
      },
    },
  });
};
