import { Box, Text } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useRef } from 'react';

import { BackgroundSection } from './../../ricos-common-plugins/layout/shared-settings-components/background-section.js';
import { EditorContext, ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import type { Background, BackgroundImage } from './../../ricos-schema/next-schema/index.js';
import { Background_Type } from './../../ricos-schema/next-schema/index.js';
import type { Gradient } from './../../ricos-types/color-palette-types.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import type { PmCardNode } from './../../_shared/pm-node-types.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { schemaGradientToCss } from './../../_shared/schema-gradient-to-css.js';
import { useEditorProps } from './../../_shared/some-editor-props-context.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { combineHexWithOpacity, getOpacityFromHex } from './../../wix-rich-content-common/index.js';
import {
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';
import { findNodeById } from './../../tiptap-editor/helpers/index.js';

import { CardColorPicker, getCardBackgroundColor } from './card-color-picker.js';
import {
  CARD_SETTINGS_MODAL_ID,
  CARD_SETTINGS_COLOR_PICKER_MODAL_ID,
  CARD_SETTINGS_BACKGROUND_TYPE_TOGGLE,
  CARD_SETTINGS_BACKGROUND_COLOR_INPUT,
  CARD_SETTINGS_BACKGROUND_COLOR_PICKER,
  CARD_SETTINGS_BACKGROUND_IMAGE_VIEWER,
  CARD_SETTINGS_BACKGROUND_SCALING_SELECT,
  CARD_SETTINGS_BACKGROUND_POSITION_SELECT,
  CARD_SETTINGS_BACKGROUND_BLUR_INPUT,
} from './data-hooks.js';
import { handleCardImageUpload } from './handle-card-image-upload.js';

type CardSettingsProps = {
  nodeId: string;
  referenceElement: HTMLElement | null;
};

export const CardSettings: FC<CardSettingsProps> = ({ nodeId, referenceElement }) => {
  const { t, isMobile, theme } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext) || {};
  const containerEl = usePanelContainerElement();
  const { pmNodeAttrs, patchPmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.CARD);
  const logBi = useBiNext({ modalId: CARD_SETTINGS_MODAL_ID, pluginId: 'card', nodeId });

  const { getPublicCommands, adapter } = useContext(EditorContext);
  const editorProps = useEditorProps();

  const backgroundColorPickerRef = useRef<HTMLDivElement>(null);

  const closeModal = () => modalService.closeModal(CARD_SETTINGS_MODAL_ID);
  const isColorPickerModalOpen = () =>
    modalService.isModalOpen(CARD_SETTINGS_COLOR_PICKER_MODAL_ID);

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;
      if (referenceElement?.contains(target as Node)) {
        return;
      }
      closeModal();
    },
    disable: isColorPickerModalOpen(),
  });

  if (!pmNodeAttrs) {
    logInvariant(new Error('Card settings: node attrs not found'));
    return null;
  }

  // With an image the active fill is the overlay (new model); otherwise the card fill.
  // Reading the correct source keeps the panel preview and the color picker (incl. its
  // preserved opacity) in sync with what's actually stored.
  const hasBackgroundImage = Boolean(pmNodeAttrs.backgroundImage);
  const activeFill = hasBackgroundImage
    ? pmNodeAttrs.backgroundImage?.overlay
    : pmNodeAttrs.background;

  const backgroundGradient =
    activeFill?.type === Background_Type.GRADIENT
      ? schemaGradientToCss(activeFill.gradient, theme.colorPalette)
      : undefined;

  const backgroundColor = getCardBackgroundColor(
    activeFill?.type === Background_Type.COLOR ? activeFill.color : undefined,
    theme?.customStyles?.card?.backgroundColor,
    hasBackgroundImage
  );

  const onValueSelected = (value: { color?: string; gradient?: Gradient } | undefined) => {
    // Changing only the color reports a fully-opaque value; keep the existing overlay/fill
    // opacity instead of overriding it to 100% by baking the previous alpha into the new
    // color. An explicit opacity change arrives with its own (<100) alpha, which we honor.
    const existingColor = activeFill?.type === Background_Type.COLOR ? activeFill.color : undefined;
    const color =
      value?.color && existingColor && getOpacityFromHex(value.color) === 100
        ? (combineHexWithOpacity(value.color, getOpacityFromHex(existingColor)) ?? value.color)
        : value?.color;

    const fill: Background =
      !value || value.color !== undefined
        ? { type: Background_Type.COLOR, color: color ?? TRANSPARENT_HEX_COLOR }
        : { type: Background_Type.GRADIENT, gradient: value.gradient! };
    // With an image, the picked color/gradient is the overlay (new model); otherwise the card fill.
    if (pmNodeAttrs.backgroundImage) {
      patchPmNodeAttrs({ backgroundImage: { ...pmNodeAttrs.backgroundImage, overlay: fill } });
    } else {
      patchPmNodeAttrs({ background: fill });
    }
  };

  const openColorPicker = (referenceEl: HTMLDivElement) => {
    const modalId = CARD_SETTINGS_COLOR_PICKER_MODAL_ID;

    modalService.togglePluginPanel({
      id: modalId,
      Component: CardColorPicker,
      componentProps: {
        modalId,
        nodeId,
        colorType: 'background' as const,
        referenceElement: referenceEl,
        onValueSelected,
      },
      isMobile,
      positioning: {
        referenceElement: referenceEl,
        placement: 'left',
      },
      type: undefined,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      focusReturnElement: referenceEl ?? undefined,
    });
  };

  const onBgImageRequest = async () => {
    const pickImage = editorProps.pickMedia?.pickImage;
    if (!pickImage) {
      return;
    }
    await handleCardImageUpload({
      pickImage,
      publicCommands: getPublicCommands(),
      nodeId,
    });
  };

  const onBgImageRemove = () => {
    patchPmNodeAttrs({ backgroundImage: undefined });
  };

  const onBackgroundChange = (
    newValue: Parameters<React.ComponentProps<typeof BackgroundSection>['onChange']>[0]
  ) => {
    // Read fresh attrs to avoid overwriting nested image fields (e.g. blur) that
    // were set between renders with a stale `pmNodeAttrs.backgroundImage` closure.
    const tr = adapter.tiptapEditor.view.state.tr;
    const freshAttrs =
      (findNodeById(tr, nodeId)[0]?.node.attrs as PmCardNode['attrs'] | undefined) ?? pmNodeAttrs;
    const currentImage = freshAttrs.backgroundImage;

    const updates: Partial<PmCardNode['attrs']> = {};

    if ('image' in newValue) {
      updates.backgroundImage = newValue.image as BackgroundImage | undefined;
    }
    if ('color' in newValue) {
      // With an image, the picked color is the overlay (new model); otherwise the card fill.
      if (currentImage) {
        updates.backgroundImage = {
          ...(updates.backgroundImage ?? currentImage),
          overlay: { type: Background_Type.COLOR, color: newValue.color! },
        };
      } else {
        updates.background = { type: Background_Type.COLOR, color: newValue.color! };
      }
    }
    if ('imageScaling' in newValue && currentImage) {
      updates.backgroundImage = {
        ...(updates.backgroundImage ?? currentImage),
        scaling: newValue.imageScaling,
      };
    }
    if ('imagePosition' in newValue && currentImage) {
      updates.backgroundImage = {
        ...(updates.backgroundImage ?? currentImage),
        position: newValue.imagePosition,
      };
    }
    if ('imageBlur' in newValue && currentImage) {
      updates.backgroundImage = {
        ...(updates.backgroundImage ?? currentImage),
        blur: newValue.imageBlur,
      };
    }

    patchPmNodeAttrs(updates);
  };

  return (
    <Panel
      onCloseButtonClick={closeModal}
      dataHook={CARD_SETTINGS_MODAL_ID}
      maxHeight={isMobile ? undefined : 590}
    >
      <PanelHeader title={t('Card_SettingsModal_Header')} />

      <Box direction="vertical" overflow="auto">
        <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
          <Box paddingBottom="SP1">
            <Text size="small" weight="bold">
              {t('Card_SettingsModal_Tab_Design_Background_Label')}
            </Text>
          </Box>
          <BackgroundSection
            imageLoading={pmNodeAttrs.loading?.backgroundImage}
            image={pmNodeAttrs.backgroundImage}
            imageScaling={pmNodeAttrs.backgroundImage?.scaling ?? 'CONTAIN'}
            imagePosition={pmNodeAttrs.backgroundImage?.position ?? 'CENTER'}
            imageBlur={pmNodeAttrs.backgroundImage?.blur ?? 0}
            color={backgroundColor}
            gradient={backgroundGradient}
            onChange={onBackgroundChange}
            openColorPicker={() => {
              openColorPicker(backgroundColorPickerRef.current!);
              logBi({ dataHook: CARD_SETTINGS_BACKGROUND_COLOR_PICKER });
            }}
            colorPickerRef={backgroundColorPickerRef}
            backgroundTypeToggleDataHook={CARD_SETTINGS_BACKGROUND_TYPE_TOGGLE}
            colorDataHook={CARD_SETTINGS_BACKGROUND_COLOR_INPUT}
            colorPickerDataHook={CARD_SETTINGS_BACKGROUND_COLOR_PICKER}
            imageDataHook={CARD_SETTINGS_BACKGROUND_IMAGE_VIEWER}
            imageScalingDataHook={CARD_SETTINGS_BACKGROUND_SCALING_SELECT}
            imagePositionDataHook={CARD_SETTINGS_BACKGROUND_POSITION_SELECT}
            imageBlurDataHook={CARD_SETTINGS_BACKGROUND_BLUR_INPUT}
            onImageRequest={onBgImageRequest}
            onImageRemove={onBgImageRemove}
            logBi={logBi}
          />
        </Box>
      </Box>
    </Panel>
  );
};
