import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { ModalServiceContext } from './../../ricos-context/modal-context.js';
import { Background_Type } from './../../ricos-schema/next-schema/index.js';
import { toHexFormat } from './../../ricos-styles/index.js';
import type { Gradient } from './../../ricos-types/color-palette-types.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded,
  handleColorDeleted,
  handleGradientAdded,
  handleGradientDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
  useResolvedCustomGradients,
} from './../../_shared/color-manager-utils.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { NewColorPicker } from './../../ui-components/color-picker/new-color-picker/index.js';

import { isTransparentCardBackgroundColor } from '../shared-with-viewer.js';
import { CARD_SETTINGS_MODAL_ID } from './data-hooks.js';

type CardColorPickerProps = {
  modalId: string;
  nodeId: string;
  referenceElement: HTMLDivElement | null;
  onValueSelected: (value: { color?: string; gradient?: Gradient } | undefined) => void;
  onColorAdded?: (color: string) => void;
  colorType: 'background';
};

const DEFAULT_CARD_BACKGROUND_COLOR = '#FFFFFF';

const toPickerColor = (color?: string): string | undefined => {
  try {
    return color ? toHexFormat(color).toUpperCase() : undefined;
  } catch {
    return undefined;
  }
};

export const getCardBackgroundColor = (
  color: string | undefined,
  defaultColor: string | undefined,
  hasBackgroundImage: boolean
): string => {
  const pickerColor = toPickerColor(color);
  if (pickerColor && !isTransparentCardBackgroundColor(pickerColor)) {
    return pickerColor;
  }

  return hasBackgroundImage
    ? TRANSPARENT_HEX_COLOR
    : (toPickerColor(defaultColor) ?? DEFAULT_CARD_BACKGROUND_COLOR);
};

export const CardColorPicker: React.FC<CardColorPickerProps> = ({
  modalId,
  nodeId,
  referenceElement,
  onValueSelected,
  onColorAdded: onColorAddedProp,
}) => {
  const modalService = useContext(ModalServiceContext);
  const { t, colorManager, theme } = useContext(RicosContext);

  const { pmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.CARD);

  const logBi = useBiNext({
    modalId: CARD_SETTINGS_MODAL_ID,
    pluginId: 'card',
    nodeId,
  });

  const themeColors = resolveThemeColorsPalette(theme);

  const customColors = useResolvedCustomColors(colorManager);
  const customGradients = useResolvedCustomGradients(colorManager);

  // With an image the active fill is the overlay (new model); otherwise the card fill.
  // Feeding the picker the stored color lets `preserveCurrentOpacity` keep the alpha when
  // only the color (swatch) changes.
  const hasBackgroundImage = Boolean(pmNodeAttrs?.backgroundImage);
  const activeFill = hasBackgroundImage
    ? pmNodeAttrs?.backgroundImage?.overlay
    : pmNodeAttrs?.background;

  const currentColor = getCardBackgroundColor(
    activeFill?.type === Background_Type.COLOR ? activeFill.color : undefined,
    theme?.customStyles?.card?.backgroundColor,
    hasBackgroundImage
  );

  const currentGradient =
    activeFill?.type === Background_Type.GRADIENT ? activeFill.gradient : undefined;

  const onColorAdded = (color: string) => {
    handleColorAdded(color, colorManager, onColorAddedProp);
    onValueSelected({ color });
  };

  const onGradientAdded = (gradient: Gradient) => {
    handleGradientAdded(gradient, colorManager);
    onValueSelected({ gradient });
  };

  const onGradientDeleted = (gradient: Gradient) => {
    handleGradientDeleted(gradient, colorManager);
  };

  const onColorDeleted = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const closeModal = () => modalService.closeModal(modalId);

  const onResetColor = () => onValueSelected(undefined);

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      customGradients={customGradients}
      currentColor={currentGradient ?? currentColor}
      fallbackColor={currentColor}
      title={t('Card_ColourModal_Title')}
      closeModal={closeModal}
      onColorSelected={color => onValueSelected(color ? { color } : undefined)}
      onGradientSelected={gradient => onValueSelected({ gradient })}
      onColorAdded={onColorAdded}
      onColorDeleted={onColorDeleted}
      onGradientAdded={onGradientAdded}
      onGradientDeleted={onGradientDeleted}
      onResetColor={onResetColor}
      referenceElement={referenceElement}
      logBi={logBi}
      allowTransparent
      allowGradient
    />
  );
};
