import { IconButton, Tooltip } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext } from 'react';

import { RicosContext } from './../ricos-context/index.js';
import { MergeSmall } from './/icons/merge-small.js';

import styles from './card-scss.js';
import { AddSmall } from './icons/add-small.js';

export type PageGapProps = {
  onAddPage: () => void;
  onMergePages: () => void;
  onMergeHoverChange: (isHovered: boolean) => void;
  isLastCard: boolean;
};

export const PageGap: FC<PageGapProps> = ({
  onAddPage,
  onMergePages,
  onMergeHoverChange,
  isLastCard,
}) => {
  const { t } = useContext(RicosContext);

  return (
    <div className={styles.cardGapAddButtonWrapper}>
      <Tooltip content={t('Card_PageGap_AddPage_Tooltip')} size="small">
        <IconButton
          className={styles.cardGapAddButton}
          onClick={onAddPage}
          size="tiny"
          skin="light"
          priority="primary"
        >
          <AddSmall />
        </IconButton>
      </Tooltip>
      {!isLastCard && (
        <Tooltip content={t('Card_PageGap_MergePages_Tooltip')} size="small">
          <IconButton
            className={styles.cardGapAddButton}
            onClick={onMergePages}
            onMouseEnter={() => onMergeHoverChange(true)}
            onMouseLeave={() => onMergeHoverChange(false)}
            size="tiny"
            skin="light"
            priority="primary"
          >
            <MergeSmall />
          </IconButton>
        </Tooltip>
      )}
    </div>
  );
};
