import { autoUpdate, offset, useFloating } from '@floating-ui/react-dom';
import { ToggleButton, Tooltip } from '@wix/design-system';
import type { FC } from 'react';
import React, { useCallback, useContext, useRef, useState } from 'react';
import ReactDOM from 'react-dom';

import { RicosContext } from './../ricos-context/index.js';

import styles from './card-scss.js';
import { SplitHorizontallySmall } from './icons/split-horizontally-small.js';

export type BoundaryLineProps = {
  visible: boolean;
  onSplit?: () => void;
  getBoundaryWarningPortal?: () => HTMLElement | null;
};

export const BoundaryLine: FC<BoundaryLineProps> = ({
  visible,
  onSplit,
  getBoundaryWarningPortal,
}) => {
  const portal = getBoundaryWarningPortal?.() ?? null;
  const { t } = useContext(RicosContext);
  const [isHovered, setIsHovered] = useState(false);
  const leaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearLeaveTimer = useCallback(() => {
    if (leaveTimer.current !== null) {
      clearTimeout(leaveTimer.current);
      leaveTimer.current = null;
    }
  }, []);

  const handleMouseEnter = useCallback(() => {
    clearLeaveTimer();
    setIsHovered(true);
  }, [clearLeaveTimer]);

  const handleMouseLeave = useCallback(() => {
    clearLeaveTimer();
    leaveTimer.current = setTimeout(() => {
      setIsHovered(false);
    }, 50);
  }, [clearLeaveTimer]);

  const {
    x,
    y,
    refs: { setReference, setFloating },
    strategy,
  } = useFloating({
    placement: 'left',
    strategy: portal ? 'fixed' : 'absolute',
    middleware: [
      offset(() => ({
        mainAxis: 8,
      })),
    ],
    whileElementsMounted: (referenceEl, floatingEl, update) =>
      autoUpdate(referenceEl, floatingEl, update, { animationFrame: true }),
  });

  const lineClassName = `${styles.cardBoundaryLineContent}${isHovered ? ` ${styles.hovered}` : ''}`;

  const iconContent = (
    <div
      ref={setFloating}
      style={{
        position: strategy,
        top: y ?? '',
        left: x ?? '',
        zIndex: 1,
      }}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className={`${styles.cardBoundaryWarning}${isHovered ? ` ${styles.hovered}` : ''}`}>
        <Tooltip content={t('Card_BoundaryWarning_Tooltip')} size="small" placement="left">
          <ToggleButton skin="inverted" selected tooltipDisabled size="small" onClick={onSplit}>
            <SplitHorizontallySmall />
          </ToggleButton>
        </Tooltip>
      </div>
    </div>
  );

  return (
    <>
      <div
        ref={setReference}
        className={lineClassName}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className={styles.cardBoundaryLine} />
      </div>
      {visible && portal && ReactDOM.createPortal(iconContent, portal)}
    </>
  );
};
