import { Box, FormField, ImageViewer, Input, SegmentedToggle } from '@wix/design-system';
import React from 'react';

import { RicosContext, ZIndexContext } from './../../../ricos-context/index.js';
import type { ImagePosition, ImageScaling } from './../../../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmLayoutNode } from './../../../_shared/pm-node-types.js';
import { getImageSrc } from './../../../wix-rich-content-common/lib/image-utils.js';
import {
  ColorWithOpacityInput,
  NumberInputWithLabel,
  PositionSelectorWithLabel,
  SelectWithLabel,
} from './../../../ui-components/index.js';

type BackgroundImage = PmLayoutNode['attrs']['backgroundImage'];
type BackgroundColor = PmLayoutNode['attrs']['backgroundColor'];

type BackgroundSectionProps = {
  imageLoading?: boolean;
  image: BackgroundImage;
  imageScaling: ImageScaling;
  imagePosition: ImagePosition;
  imageBlur: number;
  color: BackgroundColor;
  gradient?: string;
  onChange: (args: {
    image?: BackgroundImage;
    color?: BackgroundColor;
    imageScaling?: ImageScaling;
    imagePosition?: ImagePosition;
    imageBlur?: number;
  }) => void;
  openColorPicker: () => void;
  colorPickerRef: React.RefObject<HTMLDivElement>;
  backgroundTypeToggleDataHook: string;
  colorDataHook: string;
  colorPickerDataHook: string;
  imageDataHook: string;
  imageScalingDataHook: string;
  imagePositionDataHook: string;
  imageBlurDataHook: string;
  onImageRequest: () => void;
  onImageRemove: () => void;
  logBi: LogBiFn;
};

export const BackgroundSection: React.FC<BackgroundSectionProps> = ({
  imageLoading,
  image,
  imageScaling,
  imagePosition,
  imageBlur,
  color,
  gradient,
  onChange,
  openColorPicker,
  colorPickerRef,
  backgroundTypeToggleDataHook,
  colorDataHook,
  colorPickerDataHook,
  imageDataHook,
  imageScalingDataHook,
  imagePositionDataHook,
  imageBlurDataHook,
  onImageRequest,
  onImageRemove,
  logBi,
}) => {
  const zIndexService = React.useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const { t } = React.useContext(RicosContext);
  const [backgroundToggleValue, setBackgroundToggleValue] = React.useState<'color' | 'image'>(() =>
    image ? 'image' : 'color'
  );
  const [previousBackgroundImageValue, setPreviousBackgroundImageValue] =
    React.useState<BackgroundImage>(undefined);

  const changeBackgroundType = (type: 'color' | 'image') => {
    setBackgroundToggleValue(type);
    if (type === 'color') {
      setPreviousBackgroundImageValue(image);
      onChange({ image: undefined });
    } else {
      onChange({ image: previousBackgroundImageValue });
    }
  };

  const backgroundImageUrl =
    image?.media?.src.url ??
    (image?.media?.src.id &&
      getImageSrc({ file_name: image?.media?.src.id }, undefined, {
        requiredWidth: 240,
        requiredHeight: 240,
        requiredQuality: 100,
      }));

  return (
    <>
      <FormField inputWidth="100%">
        <SegmentedToggle
          defaultSelected={backgroundToggleValue}
          size="small"
          onClick={(_, value) => changeBackgroundType(value as 'color' | 'image')}
          dataHook={backgroundTypeToggleDataHook}
        >
          <SegmentedToggle.Button value={'color'}>
            {t('Layout_SettingsModal_Tab_Design_Toggle_Color')}
          </SegmentedToggle.Button>
          <SegmentedToggle.Button value={'image'}>
            {t('Layout_SettingsModal_Tab_Design_Toggle_Image')}
          </SegmentedToggle.Button>
        </SegmentedToggle>
      </FormField>
      {(() => {
        switch (backgroundToggleValue) {
          case 'color':
            return (
              <Box direction="vertical" gap="SP2">
                <ColorWithOpacityInput
                  label={t('Layout_SettingsModal_Tab_Design_Fill_Color')}
                  fill={
                    gradient
                      ? { type: 'gradient', gradient }
                      : {
                          type: 'color',
                          color,
                          onChange: color => onChange({ color }),
                          allowTransparent: true,
                        }
                  }
                  onColorPress={openColorPicker}
                  colorPickerRef={colorPickerRef}
                  inputDataHook={colorDataHook}
                  fillPreviewDataHook={colorPickerDataHook}
                  zIndex={zIndex}
                />
              </Box>
            );
          case 'image':
            return (
              <Box direction="vertical" gap="SP2">
                <ImageViewer
                  width="100%"
                  height={136}
                  tooltipProps={{ size: 'small' }}
                  imageUrl={backgroundImageUrl}
                  onAddImage={onImageRequest}
                  onUpdateImage={onImageRequest}
                  onRemoveImage={onImageRemove}
                  dataHook={imageDataHook}
                  status={imageLoading ? 'loading' : undefined}
                  showUpdateButton={!imageLoading}
                  showRemoveButton={!imageLoading}
                  addImageInfo={t('Layout_SettingsModal_Tab_Design_Image_AddImage')}
                  removeImageInfo={t('Layout_SettingsModal_Tab_Design_Image_RemoveImage')}
                  updateImageInfo={t('Layout_SettingsModal_Tab_Design_Image_UpdateImage')}
                />

                {backgroundImageUrl && (
                  <>
                    <ColorWithOpacityInput
                      label={t('Layout_SettingsModal_Tab_Design_Image_OverlayColor')}
                      fill={
                        gradient
                          ? { type: 'gradient', gradient }
                          : {
                              type: 'color',
                              color,
                              onChange: color => onChange({ color }),
                              allowTransparent: true,
                            }
                      }
                      onColorPress={openColorPicker}
                      colorPickerRef={colorPickerRef}
                      inputDataHook={colorDataHook}
                      fillPreviewDataHook={colorPickerDataHook}
                      zIndex={zIndex}
                      logBi={logBi}
                    />

                    <NumberInputWithLabel
                      label={t('Layout_SettingsModal_Tab_Design_Image_Blur')}
                      value={imageBlur}
                      min={0}
                      max={40}
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      onChange={amount => onChange({ imageBlur: amount ?? 0 })}
                      dataHook={imageBlurDataHook}
                      logBi={logBi}
                      zIndex={zIndex}
                    />

                    <SelectWithLabel<ImageScaling>
                      label={t('Layout_SettingsModal_Tab_Design_Image_BackgroundScaling')}
                      value={imageScaling}
                      onChange={scaling => onChange({ imageScaling: scaling })}
                      dataHook={imageScalingDataHook}
                      logBi={logBi}
                      options={[
                        {
                          id: 'CONTAIN',
                          value: t(
                            'Layout_SettingsModal_Tab_Design_Image_BackgroundScaling_Contain'
                          ) as string,
                        },
                        {
                          id: 'COVER',
                          value: t(
                            'Layout_SettingsModal_Tab_Design_Image_BackgroundScaling_Cover'
                          ) as string,
                        },
                        {
                          id: 'AUTO',
                          value: t(
                            'Layout_SettingsModal_Tab_Design_Image_BackgroundScaling_Auto'
                          ) as string,
                        },
                      ]}
                      zIndex={zIndex}
                    />

                    <PositionSelectorWithLabel
                      label={t('Layout_SettingsModal_Tab_Design_Image_BackgroundPosition')}
                      value={imagePosition}
                      dataHook={imagePositionDataHook}
                      onChange={position => {
                        onChange({ imagePosition: position });
                        logBi({ dataHook: imagePositionDataHook, value: position });
                      }}
                    />
                  </>
                )}
              </Box>
            );
          default:
            return null;
        }
      })()}
    </>
  );
};
