import { AngleInput } from '@wix/design-system';
import classNames from 'classnames';
import type { FC } from 'react';
import React, { useEffect, useState } from 'react';

import type { Gradient } from './../../../../../ricos-types/color-palette-types.js';
import { schemaGradientToCss } from './../../../../../_shared/schema-gradient-to-css.js';

import classes from './gradient-picker-scss.js';

type GradientPreviewProps = {
  value: Gradient;
  onChange: (gradient: Gradient) => void;
};

export const GradientPreview: FC<GradientPreviewProps> = ({ value, onChange }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mouseup', handleMouseUp);
    }

    return () => document.removeEventListener('mouseup', handleMouseUp);
  }, [isDragging]);

  const handleMouseDown = (event: React.MouseEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setIsDragging(true);
  };

  const handleMouseMove = (event: React.MouseEvent<HTMLDivElement>) => {
    if (isDragging && value.type === 'RADIAL') {
      const rect = event.currentTarget.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      const centerX = Math.round(Math.max(0, Math.min(100, (x / rect.width) * 100)));
      const centerY = Math.round(Math.max(0, Math.min(100, (y / rect.height) * 100)));
      onChange({ ...value, centerX, centerY });
    }
  };

  const handleCenterKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (value.type !== 'RADIAL') {
      return;
    }

    let x = value.centerX ?? 50;
    let y = value.centerY ?? 50;

    const step = 1;
    let changed = false;

    switch (event.key) {
      case 'ArrowLeft':
        x = Math.max(0, x - step);
        changed = true;
        break;
      case 'ArrowRight':
        x = Math.min(100, x + step);
        changed = true;
        break;
      case 'ArrowUp':
        y = Math.max(0, y - step);
        changed = true;
        break;
      case 'ArrowDown':
        y = Math.min(100, y + step);
        changed = true;
        break;
      default:
        return;
    }

    if (changed) {
      event.preventDefault();
      onChange({ ...value, centerX: x, centerY: y });
    }
  };

  return (
    <div
      className={classNames(classes.preview, {
        [classes.radial]: value.type === 'RADIAL',
      })}
      style={
        {
          '--gp-gradient': schemaGradientToCss(value),
        } as React.CSSProperties
      }
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
    >
      {value.type === 'LINEAR' && (
        <AngleInput
          value={value.angle ?? 90}
          step={1}
          onChange={angle => onChange({ ...value, angle })}
        />
      )}
      {value.type === 'RADIAL' && (
        <div
          role="button"
          tabIndex={0}
          aria-live="polite"
          className={classes.radialCenter}
          style={
            {
              '--gp-radial-center-x': `${value.centerX ?? 50}%`,
              '--gp-radial-center-y': `${value.centerY ?? 50}%`,
            } as React.CSSProperties
          }
          onKeyDown={handleCenterKeyDown}
        />
      )}
    </div>
  );
};
