import type { SidePanelProps } from '@wix/design-system';
import { SidePanel } from '@wix/design-system';
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { PANEL_HEADER_ID } from './../consts.js';
import { UiComponentsPopoverAppendToProvider } from './../ui-components-provider.js';

import classes from './panel-scss.js';

type Props = React.PropsWithChildren<SidePanelProps>;

const appendToPanelRoot = (element: Element) => element.classList.contains(classes.modal);

export const Panel: React.FC<Props> = ({ children, dataHook, ...props }) => {
  const { isMobile, environment, t } = useContext(RicosContext);

  return (
    <div role="dialog" aria-modal="true" aria-labelledby={PANEL_HEADER_ID}>
      <SidePanel
        width={isMobile ? '100%' : 288}
        height={isMobile ? '100dvh' : 'fit-content'}
        {...props}
        dataHook={classNames('floating-layout-root', dataHook)}
        skin="floating"
        className={classNames(classes.modal, { [classes.liveSite]: environment === 'liveSite' })}
        closeButtonProps={{
          ariaLabel: t('Panel_CloseButton_AriaLabel'),
          ...props.closeButtonProps,
        }}
      >
        <UiComponentsPopoverAppendToProvider appendTo={appendToPanelRoot}>
          {children}
        </UiComponentsPopoverAppendToProvider>
      </SidePanel>
    </div>
  );
};
