import type { FC } from 'react';

import { TIPTAP_CARD_CONTENT_TYPE, TIPTAP_CARD_TYPE } from './../ricos-content/index.js';
import type { BackgroundImage, Background } from './../ricos-schema/next-schema/index.js';
import { resolveBackwardCompatOverlay } from './../_shared/resolve-backward-compat-overlay.js';
import type { Editor, NodeViewRenderer } from './../tiptap/core/index.js';
import type { Node as PmNode } from './../tiptap/pm/model.js';
import { ReactRenderer } from './../tiptap/react/index.js';
import { getImageSrc } from './../wix-rich-content-common/lib/image-utils.js';

import { gradientToCss } from '../_shared/gradient-to-css.js';
import { hexToRgba } from '../theme-utils/color-utils.js';
import type { BoundaryLineProps } from './boundary-warning.js';
import { BoundaryLine } from './boundary-warning.js';
import styles from './card-scss.js';
import { PageGap } from './page-gap.js';
import {
  CARD_DEFAULTS,
  getCardBackgroundColorCssVar,
  isTransparentCardBackgroundColor,
} from './shared-with-viewer.js';
import type { CardHeaderProps, CardFormat, CardExtensionStorage } from './types.js';

// Helper to check if selection intersects with a card node
const isSelectionInCard = (
  editor: Editor,
  getPos: () => number | undefined,
  nodeSize: number
): boolean => {
  const pos = getPos();
  if (typeof pos !== 'number') {
    return false;
  }

  const { from, to } = editor.state.selection;
  const cardStart = pos;
  const cardEnd = pos + nodeSize;

  // Check if selection intersects with the card range
  return from < cardEnd && to > cardStart;
};

const isFluidPageFormat = (pageFormat: CardFormat | undefined): boolean =>
  pageFormat !== undefined && pageFormat.height === undefined;

const getCardStorage = (editor: Editor): CardExtensionStorage =>
  editor.storage[TIPTAP_CARD_TYPE] as CardExtensionStorage;

const getActivePageFormat = (editor: Editor): CardFormat | undefined =>
  getCardStorage(editor)?.activePageFormat;

const setOrRemove = (el: HTMLElement, prop: string, value: string | undefined): void => {
  if (value !== undefined) {
    el.style.setProperty(prop, value);
  } else {
    el.style.removeProperty(prop);
  }
};

const updateCardBackgroundStyles = (cardElement: HTMLDivElement, node: PmNode): void => {
  const background: Background | undefined = node.attrs.background;
  const backgroundImage: BackgroundImage | undefined = node.attrs.backgroundImage;

  // When any explicit background is set, block theme inheritance for all layers.
  // Zero-alpha color is the "cleared" state — it should inherit from theme.
  const isTransparentColor =
    background?.type === 'COLOR' && isTransparentCardBackgroundColor(background.color);
  const hasExplicitBackground = (!!background && !isTransparentColor) || !!backgroundImage;

  // When an image is set, `background` plays the role of the *overlay* (on top
  // of the image). Otherwise it's the card fill (color or gradient).
  if (backgroundImage) {
    const imageUrl =
      backgroundImage.media?.src.url ??
      (backgroundImage.media?.src.id &&
        getImageSrc({ file_name: backgroundImage.media.src.id }, undefined, {
          requiredQuality: 100,
          requiredWidth: Math.min(backgroundImage.media?.width ?? 4000, 4000),
          requiredHeight: Math.min(backgroundImage.media?.height ?? 4000, 4000),
        }));

    setOrRemove(
      cardElement,
      '--ricos-internal-card-background-image',
      imageUrl ? `url(${imageUrl})` : undefined
    );
    setOrRemove(
      cardElement,
      '--ricos-internal-card-background-size',
      backgroundImage.scaling?.toLowerCase()
    );
    setOrRemove(
      cardElement,
      '--ricos-internal-card-background-position',
      backgroundImage.position?.toLowerCase().split('_').join(' ')
    );

    // `backgroundImage.overlay` (new model) is authoritative when present; otherwise the legacy
    // `background` fill doubles as the overlay through the opacity shim.
    let overlay: string | undefined;
    if (backgroundImage.overlay?.type === 'GRADIENT') {
      overlay = gradientToCss(backgroundImage.overlay.gradient) || undefined;
    } else if (backgroundImage.overlay?.type === 'COLOR') {
      overlay = hexToRgba(backgroundImage.overlay.color);
    } else if (background?.type === 'GRADIENT') {
      overlay = gradientToCss(background.gradient) || undefined;
    } else if (background?.type === 'COLOR' && !isTransparentColor) {
      const resolved = resolveBackwardCompatOverlay(
        background.color,
        backgroundImage.opacity ?? 100,
        100
      );
      overlay = hexToRgba(resolved);
    }
    setOrRemove(cardElement, '--ricos-internal-card-background-image-overlay', overlay);

    // Color/gradient base layer is unused when an image is shown — clear stale vars
    cardElement.style.removeProperty('--ricos-internal-card-background-color');
    cardElement.style.removeProperty('--ricos-internal-card-background-gradient');
    cardElement.style.removeProperty('--ricos-internal-card-background-image-opacity');
  } else {
    const gradientCss =
      background?.type === 'GRADIENT' ? gradientToCss(background.gradient) : undefined;
    // Color/gradient layer (container fill)
    // Use 'transparent' to block theme color when card has explicit background but no color
    setOrRemove(
      cardElement,
      '--ricos-internal-card-background-color',
      getCardBackgroundColorCssVar(background, hasExplicitBackground)
    );
    setOrRemove(cardElement, '--ricos-internal-card-background-gradient', gradientCss || undefined);
    cardElement.style.removeProperty('--ricos-internal-card-background-image-overlay');

    if (hasExplicitBackground) {
      // Card has explicit color/gradient but no image — block theme image with 'none'
      cardElement.style.setProperty('--ricos-internal-card-background-image', 'none');
    } else {
      // No explicit background — remove internal var so theme applies
      cardElement.style.removeProperty('--ricos-internal-card-background-image');
    }
    cardElement.style.removeProperty('--ricos-internal-card-background-size');
    cardElement.style.removeProperty('--ricos-internal-card-background-position');
    cardElement.style.removeProperty('--ricos-internal-card-background-image-opacity');
  }
};

const updateCardView = (
  cardElement: HTMLDivElement,
  contentElement: HTMLDivElement,
  boundaryLineWrapper: HTMLDivElement,
  boundaryLineRenderer: ReactRenderer<unknown, BoundaryLineProps>,
  pageFormat: CardFormat | undefined,
  hideBoundaryLine?: boolean,
  onSplit?: () => void
): void => {
  const width = pageFormat?.width ?? CARD_DEFAULTS.width;
  const isFluid = isFluidPageFormat(pageFormat);

  cardElement.style.setProperty('--ricos-internal-card-width', `${width}px`);

  if (isFluid) {
    cardElement.style.removeProperty('--ricos-internal-card-height');
    cardElement.classList.add(styles.fluid);
    contentElement.classList.add(styles.fluidContent);
    boundaryLineWrapper.classList.remove(styles.visible);
    boundaryLineRenderer.updateProps({ visible: false, onSplit });
  } else {
    const height = pageFormat?.height ?? CARD_DEFAULTS.height;
    cardElement.style.setProperty('--ricos-internal-card-height', `${height}px`);
    cardElement.classList.remove(styles.fluid);
    contentElement.classList.remove(styles.fluidContent);

    // Check if content overflows the defined height
    // scrollHeight includes the element's padding, so compare directly to card height
    const isOverflowing = !hideBoundaryLine && contentElement.scrollHeight > height;
    boundaryLineWrapper.classList.toggle(styles.visible, isOverflowing);
    boundaryLineRenderer.updateProps({ visible: isOverflowing, onSplit });
  }
};

type CreateCardNodeViewOptions = {
  renderCardHeader?: FC<CardHeaderProps>;
  isMobile?: boolean;
  getBoundaryWarningPortal?: () => HTMLElement | null;
};

export const createCardNodeView = (options: CreateCardNodeViewOptions): NodeViewRenderer => {
  const { renderCardHeader, isMobile, getBoundaryWarningPortal } = options;

  return ({ node, editor, getPos }) => {
    let currentNode = node;

    // Create wrapper to hold header + card + gap
    const cardWrapper = document.createElement('div');
    cardWrapper.className = styles.cardWrapper;

    // Header container for React component
    let headerContainer: HTMLDivElement | null = null;
    let headerRenderer: ReactRenderer<CardHeaderProps> | null = null;

    // Helper to calculate current card index, accounting for pending AI insertions
    const getCardIndex = (): number => {
      const doc = editor.state.doc;
      const cardPos = getPos();
      if (typeof cardPos !== 'number') {
        return 0;
      }

      let currentIndex = 0;
      let found = false;
      doc.forEach((docNode, pos) => {
        if (found) {
          return;
        }
        if (docNode.type.name === 'CARD') {
          currentIndex++;
          if (pos === cardPos) {
            found = true;
          }
        }
      });

      // Shift index for any pending AI-inserted cards that precede this card
      const pendingInsertions = getCardStorage(editor).pendingCardInsertions;
      for (const insertion of pendingInsertions) {
        // insertion.afterCardIndex is 0-based; currentIndex is 1-based
        if (insertion.afterCardIndex < currentIndex) {
          currentIndex += insertion.count;
        }
      }

      return currentIndex;
    };

    const getIsLastCard = (): boolean => {
      const doc = editor.state.doc;
      const cardPos = getPos();
      if (typeof cardPos !== 'number') {
        return true;
      }

      let isLast = true;
      let foundCurrent = false;
      doc.forEach((docNode, pos) => {
        if (docNode.type.name === 'CARD') {
          if (foundCurrent) {
            isLast = false;
            return;
          }
          if (pos === cardPos) {
            foundCurrent = true;
          }
        }
      });

      return isLast;
    };

    // Setup header renderer if renderCardHeader is provided
    if (renderCardHeader) {
      headerContainer = document.createElement('div');
      headerContainer.setAttribute('contenteditable', 'false');
      headerContainer.className = styles.cardHeaderContainer;

      headerRenderer = new ReactRenderer(renderCardHeader, {
        editor,
        props: {
          cardNode: currentNode,
          index: getCardIndex(),
        },
      });

      headerContainer.appendChild(headerRenderer.element);
      cardWrapper.appendChild(headerContainer);
    }

    const cardElement = document.createElement('div');
    cardElement.setAttribute('data-card-container', 'true');
    cardElement.setAttribute('data-card-id', currentNode.attrs.id);
    cardElement.className = styles.cardContainer;

    // CARD's contentDOM — PM mounts CARD_CONTENT and (optionally) CARD_FOOTER child NodeViews here.
    const contentElement = document.createElement('div');
    contentElement.className = styles.cardContent;

    // Boundary line element - positioned at the card height
    const boundaryLineWrapper = document.createElement('div');
    boundaryLineWrapper.setAttribute('contenteditable', 'false');
    boundaryLineWrapper.className = styles.cardBoundaryLineWrapper;

    const handleSplitAtBoundary = (): void => {
      const lineRect = boundaryLineWrapper.getBoundingClientRect();
      const posResult = editor.view.posAtCoords({
        left: lineRect.left + lineRect.width,
        top: lineRect.top - 30,
      });
      if (posResult) {
        editor.commands.splitCardAtPos(posResult.pos);
      }
    };

    const boundaryLineRenderer = new ReactRenderer(BoundaryLine, {
      editor,
      props: { visible: false, onSplit: handleSplitAtBoundary, getBoundaryWarningPortal },
    });
    boundaryLineWrapper.appendChild(boundaryLineRenderer.element);

    // Selection SVG overlay
    const selectionSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    selectionSvg.setAttribute('width', '100%');
    selectionSvg.setAttribute('height', '100%');
    selectionSvg.setAttribute('class', styles.selectionSvg);

    const selectionRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    selectionRect.setAttribute('width', '100%');
    selectionRect.setAttribute('height', '100%');
    selectionRect.setAttribute('class', styles.selectionRect);
    selectionSvg.appendChild(selectionRect);

    cardElement.append(contentElement, boundaryLineWrapper, selectionSvg);

    // Gap element with add button
    const cardGap = document.createElement('div');
    cardGap.className = styles.cardGap;
    cardGap.setAttribute('contenteditable', 'false');

    const updateLastCardClass = (): void => {
      const isLast = getIsLastCard();
      cardElement.classList.toggle(styles.last, isLast);
      cardGap.classList.toggle(styles.last, isLast);
    };
    updateLastCardClass();

    const handleAddPage = (): void => {
      const pos = getPos();
      if (typeof pos === 'number') {
        const insertPos = pos + currentNode.nodeSize;
        editor
          .chain()
          .focus()
          .insertContentAt(insertPos, {
            type: 'CARD',
            content: [
              {
                type: TIPTAP_CARD_CONTENT_TYPE,
                content: [{ type: 'PARAGRAPH' }],
              },
            ],
          })
          .run();
      }
    };

    const handleMergePages = (): void => {
      cardGap.classList.remove(styles.mergeHover);
      const cardPos = getPos();
      if (typeof cardPos === 'number') {
        let cardIdx = -1;
        let current = 0;
        editor.state.doc.forEach((docNode, offset) => {
          if (docNode.type.name === 'CARD') {
            if (offset === cardPos) {
              cardIdx = current;
            }
            current++;
          }
        });
        if (cardIdx >= 0) {
          editor.chain().focus().mergeCardWithNext(cardIdx).run();
        }
      }
    };

    const handleMergeHoverChange = (isHovered: boolean): void => {
      cardGap.classList.toggle(styles.mergeHover, isHovered);
    };

    const pageGapRenderer = new ReactRenderer(PageGap, {
      editor,
      props: {
        onAddPage: handleAddPage,
        onMergePages: handleMergePages,
        onMergeHoverChange: handleMergeHoverChange,
        isLastCard: getIsLastCard(),
      },
    });

    cardGap.appendChild(pageGapRenderer.element);
    cardWrapper.append(cardElement, cardGap);

    // ResizeObserver to detect content changes and check overflow
    const resizeObserver = new ResizeObserver(() => {
      updateCardView(
        cardElement,
        contentElement,
        boundaryLineWrapper,
        boundaryLineRenderer,
        getActivePageFormat(editor),
        isMobile,
        handleSplitAtBoundary
      );
    });

    // Selection tracking - update selected class when selection changes and editor is focused
    const updateSelectionState = (): void => {
      const isSelected =
        editor.isFocused && isSelectionInCard(editor, getPos, currentNode.nodeSize);
      const className = isSelected
        ? `${styles.selectionRect} ${styles.selectionRectActive}`
        : styles.selectionRect;
      selectionRect.setAttribute('class', className);
    };

    // Listen for selection updates and focus changes
    editor.on('selectionUpdate', updateSelectionState);
    editor.on('focus', updateSelectionState);
    editor.on('blur', updateSelectionState);

    // Update header, page gap, and last-card class when cards are added/removed
    const updateHeaderIndex = (): void => {
      if (headerRenderer) {
        headerRenderer.updateProps({
          cardNode: currentNode,
          index: getCardIndex(),
        });
      }
      pageGapRenderer.updateProps({
        isLastCard: getIsLastCard(),
      });
      updateLastCardClass();
    };

    // Listen for document updates to re-render header when card count changes
    editor.on('update', updateHeaderIndex);

    // Register for page format changes to re-render card dimensions
    const handlePageFormatChange = (): void => {
      updateCardView(
        cardElement,
        contentElement,
        boundaryLineWrapper,
        boundaryLineRenderer,
        getActivePageFormat(editor),
        isMobile,
        handleSplitAtBoundary
      );
    };
    getCardStorage(editor).onPageFormatChange.add(handlePageFormatChange);

    // Re-render header when pending AI card insertions change
    getCardStorage(editor).onPendingCardInsertionsChange.add(updateHeaderIndex);

    // Initial update
    updateCardView(
      cardElement,
      contentElement,
      boundaryLineWrapper,
      boundaryLineRenderer,
      getActivePageFormat(editor),
      undefined,
      handleSplitAtBoundary
    );
    updateCardBackgroundStyles(cardElement, currentNode);
    updateSelectionState();

    let destroyed = false;

    // Start observing after a frame to ensure content is rendered
    requestAnimationFrame(() => {
      if (!destroyed) {
        resizeObserver.observe(contentElement);
      }
    });

    return {
      dom: cardWrapper,
      contentDOM: contentElement,
      update: (newNode: PmNode) => {
        if (newNode.type !== currentNode.type) {
          return false;
        }

        currentNode = newNode;

        cardElement.setAttribute('data-card-id', newNode.attrs.id);

        updateCardView(
          cardElement,
          contentElement,
          boundaryLineWrapper,
          boundaryLineRenderer,
          getActivePageFormat(editor),
          undefined,
          handleSplitAtBoundary
        );
        updateCardBackgroundStyles(cardElement, currentNode);

        // Update header renderer props
        if (headerRenderer) {
          headerRenderer.updateProps({
            cardNode: currentNode,
            index: getCardIndex(),
          });
        }

        // Update page gap visibility of merge button and last-card class
        pageGapRenderer.updateProps({
          isLastCard: getIsLastCard(),
        });
        updateLastCardClass();

        return true;
      },
      ignoreMutation: (mutation: MutationRecord | { type: 'selection'; target: Node }) => {
        // Ignore mutations on the wrapper
        const isMutatingWrapper = mutation.target === cardWrapper;

        // Ignore mutations on the header container
        const isMutatingHeader =
          headerContainer &&
          (mutation.target === headerContainer ||
            headerContainer.contains(mutation.target as Node));

        // Ignore mutations on the card container's attributes (data-*, style, class)
        const isMutatingCardAttributes =
          mutation.target === cardElement && mutation.type === 'attributes';

        // Ignore mutations on the boundary line (class toggling for visibility)
        const isMutatingBoundaryLine =
          mutation.target === boundaryLineWrapper ||
          boundaryLineWrapper.contains(mutation.target as Node);

        // Ignore mutations on the gap and add button
        const isMutatingGap =
          mutation.target === cardGap || cardGap.contains(mutation.target as Node);

        // Ignore mutations on the selection SVG (class toggling for selection state)
        const isMutatingSelectionSvg =
          mutation.target === selectionSvg || mutation.target === selectionRect;

        // Ignore data attribute mutations
        const isMutatingDataAttribute =
          mutation.type === 'attributes' && mutation.attributeName?.startsWith('data-');

        // Ignore style attribute mutations
        const isMutatingStyle =
          mutation.type === 'attributes' && mutation.attributeName === 'style';

        // Ignore class attribute mutations
        const isMutatingClass =
          mutation.type === 'attributes' && mutation.attributeName === 'class';

        return (
          isMutatingWrapper ||
          isMutatingHeader ||
          isMutatingCardAttributes ||
          isMutatingBoundaryLine ||
          isMutatingGap ||
          isMutatingSelectionSvg ||
          isMutatingDataAttribute ||
          isMutatingStyle ||
          isMutatingClass
        );
      },
      destroy: () => {
        destroyed = true;
        resizeObserver.disconnect();
        editor.off('selectionUpdate', updateSelectionState);
        editor.off('focus', updateSelectionState);
        editor.off('blur', updateSelectionState);
        editor.off('update', updateHeaderIndex);
        getCardStorage(editor).onPageFormatChange.delete(handlePageFormatChange);
        getCardStorage(editor).onPendingCardInsertionsChange.delete(updateHeaderIndex);
        boundaryLineRenderer.destroy();
        pageGapRenderer.destroy();
        if (headerRenderer) {
          headerRenderer.destroy();
        }
      },
    };
  };
};
